# Figure 7 (new): PanIN/gland-forming-stage GALNT enzymes in PDAC Visium (Elhossiny 2026). Spec: 00_meta/figure7_spec_v1.md amendments A5/A5b. Exploratory.
suppressPackageStartupMessages({library(data.table); library(ggplot2); library(patchwork)})
root <- "${PROJECT_ROOT}"; r7 <- file.path(root, "04_results/2026-10-12_Figure7_GALNT_run01"); r6 <- file.path(root, "04_results/2026-10-12_Figure6_GALNT_run01"); out <- file.path(root, "05_figures/2026-10-12_Figure7_GALNT_run01")
fam <- "Arial"; theme_pub <- function(bs = 6) theme_classic(base_size = bs, base_family = fam) + theme(axis.line = element_line(linewidth = 0.25), axis.ticks = element_line(linewidth = 0.25), plot.title = element_text(size = bs + 0.5, face = "bold"), legend.key.size = unit(2.6, "mm"), legend.title = element_text(size = bs), legend.text = element_text(size = bs - 0.5), plot.margin = margin(2, 3, 2, 2), plot.tag = element_text(size = 9, face = "bold", family = fam), plot.tag.position = c(0, 1))
G <- c("GALNT3", "GALNT4", "GALNT7", "GALNT12", "GALNT10", "GALNT1", "GALNT2", "GALNT11"); gcl <- c(GALNT3 = "#7B52A6", GALNT4 = "#7B52A6", GALNT7 = "#7B52A6", GALNT12 = "#7B52A6", GALNT10 = "#B7791F", GALNT1 = "grey35", GALNT2 = "grey35", GALNT11 = "grey35")
## A detectability
det <- fread(file.path(r7, "H7f_detectability.csv")); dl <- melt(det, id.vars = c("gene", "detectable_all", "detectable_epi"), measure.vars = c("E_all", "E_epi", "P_all", "P_epi")); dl[, ds := factor(variable, c("E_all", "E_epi", "P_all", "P_epi"), c("PDAC\nall", "PDAC\nepi.", "PanIN\nall", "PanIN\nepi."))]
ord <- det[order(-pmin(E_epi, P_epi))]$gene; dl[, gene := factor(gene, levels = rev(ord))]; dl[, sel := fifelse(gene %in% G, "bold", "plain")]
pA <- ggplot(dl, aes(ds, gene, fill = value)) + geom_tile(colour = "white", linewidth = 0.3) + geom_text(aes(label = sprintf("%.0f", value * 100), colour = value > 0.5), size = 3.9 / .pt, family = fam) + scale_colour_manual(values = c("TRUE" = "white", "FALSE" = "black"), guide = "none") + scale_fill_gradient(low = "white", high = "#1F4E79", limits = c(0, 0.8), oob = scales::squish, name = "% spots\ndetected") +
  geom_hline(yintercept = length(ord) - 8 + 0.5, linetype = 2, linewidth = 0.25) + labs(x = NULL, y = NULL, title = "Detection in Visium (% spots)", tag = "A") + theme_pub() + theme(axis.text.y = element_text(size = 4.8), axis.text.x = element_text(size = 5), axis.line = element_blank(), axis.ticks = element_blank(), legend.key.height = unit(5, "mm"), legend.key.width = unit(2, "mm"), legend.title = element_text(size = 5))
## B maps
mp <- fread(file.path(r7, "H7f_section_map_Patient_24_SP.csv.gz")); mp[, dom := fifelse(SpatialDomain %in% c("PanIN/GLTumor", "PDTumor"), SpatialDomain, fifelse(grepl("^Fibro", SpatialDomain), "Fibroblast", "Other"))]
mapb <- function() list(coord_fixed(), scale_y_reverse(), theme_void(base_family = fam), theme(plot.margin = margin(1, 1, 1, 1), plot.title = element_text(size = 6, face = "bold", hjust = 0.5), legend.position = "bottom", legend.text = element_text(size = 4.6), legend.title = element_text(size = 5), legend.key.size = unit(2, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(0.3, "mm")))
domc <- c("PanIN/GLTumor" = "#E3B23C", "PDTumor" = "#C9453B", "Fibroblast" = "#8FA3B5", "Other" = "grey88")
pB1 <- ggplot(mp, aes(x, y, colour = dom)) + geom_point(size = 0.1, shape = 16) + scale_colour_manual(values = domc, labels = c("PanIN/GL", "PD", "Fibroblast", "Other"), breaks = names(domc), name = NULL) + mapb() + labs(title = "Domains (Patient_24)", tag = "B") + guides(colour = guide_legend(nrow = 2, override.aes = list(size = 1.4)))
gmap <- function(v, ttl) ggplot(mp, aes(x, y, colour = .data[[v]])) + geom_point(size = 0.1, shape = 16) + scale_colour_gradient(low = "grey90", high = "#6A2C91", name = NULL, limits = c(0, NA)) + mapb() + labs(title = ttl) + guides(colour = guide_colourbar(barwidth = 3, barheight = 0.3))
pB2 <- ggplot(mp, aes(x, y, colour = epi_w)) + geom_point(size = 0.1, shape = 16) + scale_colour_gradient(low = "grey90", high = "#C9453B", name = NULL) + mapb() + labs(title = "Tumor-epithelial weight") + guides(colour = guide_colourbar(barwidth = 3, barheight = 0.3))
pB3 <- gmap("GALNT3", "GALNT3"); pB4 <- ggplot(mp, aes(x, y, colour = GALNT10)) + geom_point(size = 0.1, shape = 16) + scale_colour_gradient(low = "grey90", high = "#B7791F", name = NULL, limits = c(0, NA)) + mapb() + labs(title = "GALNT10") + guides(colour = guide_colourbar(barwidth = 3, barheight = 0.3))
## C lesion axis, section-level
sm <- fread(file.path(r7, "H7f_section_group_means.csv")); sl <- melt(sm, id.vars = c("sample_Id", "tissue", "grp", "n"), measure.vars = G, variable.name = "gene", value.name = "v"); sl[, grp := factor(grp, c("Normal duct", "PanIN/GL tumor", "PD tumor"), c("Normal\nduct", "PanIN/GL\ntumor", "PD\ntumor"))]; sl[, gene := factor(gene, levels = G)]
pw <- rbindlist(lapply(G, function(g) { w <- dcast(sl[gene == g & grp != "Normal\nduct"], sample_Id ~ grp, value.var = "v"); p1 <- wilcox.test(sl[gene == g & grp == "PanIN/GL\ntumor"]$v, sl[gene == g & grp == "Normal\nduct"]$v, exact = TRUE)$p.value; p2 <- wilcox.test(w[["PanIN/GL\ntumor"]], w[["PD\ntumor"]], paired = TRUE, exact = TRUE)$p.value; data.table(gene = factor(g, G), t = sprintf("GL vs N p=%.3f\nGL vs PD p=%.3f", p1, p2)) }))
pC <- ggplot(sl, aes(grp, v)) + geom_line(data = sl[grp != "Normal\nduct"], aes(group = sample_Id), colour = "grey70", linewidth = 0.25) + geom_boxplot(aes(fill = gene), width = 0.5, outlier.shape = NA, linewidth = 0.25, alpha = 0.5, show.legend = FALSE) + geom_point(size = 0.7, position = position_jitter(width = 0.08, height = 0, seed = 1)) + geom_text(data = pw, aes(x = 2, y = Inf, label = t), vjust = 1.1, size = 3.4 / .pt, family = fam, lineheight = 0.9, inherit.aes = FALSE) +
  facet_wrap(~gene, scales = "free_y", nrow = 2) + scale_x_discrete(limits = levels(sl$grp)) + scale_fill_manual(values = gcl) + scale_y_continuous(expand = expansion(mult = c(0.05, 0.38))) + labs(x = NULL, y = "Section mean (log1p CP10k)", title = "Lesion axis in Elhossiny Visium (one dot = one section, 7 per group)", tag = "C") + theme_pub() + theme(strip.background = element_blank(), strip.text = element_text(size = 5.5, face = "bold"), axis.text.x = element_text(size = 4.6))
## D co-localisation, E niche (post hoc epithelial list)
co <- fread(file.path(r7, "H7f_colocalization_posthoc_epithelial.csv")); tl <- c("Tumor-Epithelial", "Ducts", "Acinar", "Fibroblasts", "myCAF", "iCAF", "Pericytes", "Endothelial", "Macrophages", "T-Cells")
heat <- function(d, ycol, lev, ttl, tag) { d <- d[get(ycol) %in% lev]; d[, y := factor(get(ycol), levels = rev(lev))]; d[, gene := factor(gene, levels = G)]; d[, star := fifelse(sections_pos >= 7 | sections_pos <= 0, "\u2020", "")]
  ggplot(d, aes(gene, y, fill = pooled_rho)) + geom_tile(colour = "white", linewidth = 0.3) + geom_text(aes(label = sprintf("%.2f%s", pooled_rho, star)), size = 3.6 / .pt, family = fam) + scale_fill_gradient2(low = "#2E6FB7", mid = "white", high = "#C9453B", midpoint = 0, limits = c(-0.3, 0.3), oob = scales::squish, name = "rho") + labs(x = NULL, y = NULL, title = ttl, tag = tag) + theme_pub() + theme(axis.text.y = element_text(size = 5), axis.text.x = element_text(size = 5, angle = 45, hjust = 1), axis.line = element_blank(), axis.ticks = element_blank(), legend.key.height = unit(5, "mm"), legend.key.width = unit(2, "mm")) }
pD <- heat(co[gene %in% G], "target", tl, "Co-localisation with cell types", "D")
ni <- fread(file.path(r7, "H7f_epithelial_niche_posthoc_epithelial.csv")); pE <- heat(ni[gene %in% G], "feature", c("purity", "Fibroblasts", "myCAF", "iCAF", "Endothelial", "Macrophages", "T-Cells", "Ducts"), "Niche of epithelial spots", "E")
## F concordance with PanIN grade slope (GSE254829)
gt <- fread(file.path(r6, "H1_all_gene_trend.csv")); lx <- fread(file.path(r7, "H7f_lesion_axis_Elhossiny_posthoc_epithelial.csv")); cc <- merge(gt[gene %in% G, .(gene, panin = beta_per_grade)], lx[, .(gene, ehl = PanINGL_vs_normal)], by = "gene"); cc[, gene := factor(gene, levels = G)]
pF <- ggplot(cc, aes(panin, ehl, colour = gene)) + geom_hline(yintercept = 0, linewidth = 0.25, colour = "grey60") + geom_vline(xintercept = 0, linewidth = 0.25, colour = "grey60") + geom_point(size = 1.4) + ggrepel::geom_text_repel(aes(label = gene), size = 4.2 / .pt, family = fam, segment.size = 0.2, min.segment.length = 0.1, show.legend = FALSE) + scale_colour_manual(values = gcl, guide = "none") + labs(x = "GSE254829: slope per PanIN grade step", y = "Elhossiny: PanIN/GL tumor vs normal duct", title = "Two Visium datasets, same direction?", tag = "F") + theme_pub()
## assemble
top <- wrap_plots(pA, wrap_plots(pB1, pB2, pB3, pB4, nrow = 1), nrow = 1, widths = c(1.3, 4.2)); mid <- wrap_plots(pC, pF, nrow = 1, widths = c(3.9, 1.6)); bot <- wrap_plots(pD, pE, nrow = 1, widths = c(1.07, 1))
tg_th <- theme(text = element_text(family = fam), plot.tag = element_text(face = "bold", size = 10, family = fam), plot.tag.position = c(0, 1))  # one tag size for every panel (B uses theme_void, which had fallen back to the default tag size)
rws <- lapply(list(top, mid, bot), function(r) wrap_elements(full = r & tg_th))  # rows do not share gutters
comp <- wrap_plots(rws, ncol = 1, heights = c(2.5, 3.0, 2.5)) & theme(text = element_text(family = fam))
W <- 7.2; Hh <- 8.4; ggsave(file.path(out, "Figure7.svg"), comp, width = W, height = Hh, device = svglite::svglite); ggsave(file.path(out, "Figure7.png"), comp, width = W, height = Hh, dpi = 400, device = ragg::agg_png); ggsave(file.path(out, "Figure7.tiff"), comp, width = W, height = Hh, dpi = 600, device = ragg::agg_tiff, compression = "lzw"); cat("done\n")
